def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = max((c for c in counts if c != background), key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == foreground]
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    for c in range(left, right + 1):
        if out[top][c] == background:
            out[top][c] = 2
        if out[bottom][c] == background:
            out[bottom][c] = 2
    for r in range(top, bottom + 1):
        if out[r][left] == background:
            out[r][left] = 2
        if out[r][right] == background:
            out[r][right] = 2
    return out
